"""Rapport d'audit de sécurité — NURU V12 Phase 1, Sprint 8.

Classe:
    AuditReport: Rapport structuré avec findings, severity, statistiques.
    generate_report(): Génération de rapport formaté.

Utilisation:
    report = AuditReport()
    report.add_finding(module="shell_exec.py", check="...", severity="HIGH",
                       status="PASS", description="...")
    print(report.generate_report())
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field, asdict
from datetime import datetime
from typing import Any


# ── Severity constants ───────────────────────────────────────────


class SeverityLevel:
    """Niveaux de sévérité normalisés."""

    CRITICAL = "CRITICAL"
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"
    LOW = "LOW"
    INFO = "INFO"

    ALL = (CRITICAL, HIGH, MEDIUM, LOW, INFO)

    _order = {CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3, INFO: 4}

    @classmethod
    def sort_key(cls, severity: str) -> int:
        return cls._order.get(severity, 99)


# ── Finding ──────────────────────────────────────────────────────


@dataclass
class Finding:
    """Un finding individuel d'audit.

    Attributes:
        module: Module source du finding (ex: shell_exec.py).
        check: Nom du check effectué.
        severity: Niveau de sévérité (CRITICAL, HIGH, MEDIUM, LOW, INFO).
        status: Statut (PASS, FAIL, FIXED).
        description: Description textuelle du finding.
        recommendation: Recommandation (optionnelle).
    """

    module: str
    check: str
    severity: str
    status: str
    description: str
    recommendation: str = ""

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


# ── CorrectiveAction ─────────────────────────────────────────────


@dataclass
class CorrectiveAction:
    """Action corrective appliquée.

    Attributes:
        module: Module modifié.
        description: Description du correctif.
        files: Liste des fichiers modifiés.
    """

    module: str
    description: str
    files: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


# ── AuditReport ──────────────────────────────────────────────────


class AuditReport:
    """Rapport d'audit de sécurité structuré.

    Collecte les findings, génère des statistiques et produit
    un rapport textuel ou JSON.

    Utilisation:
        report = AuditReport()
        report.add_finding(...)
        report.add_corrective_action(...)
        text = report.generate_report()
    """

    def __init__(self) -> None:
        self.findings: list[Finding] = []
        self.corrective_actions: list[CorrectiveAction] = []
        self.timestamp: str = datetime.now().isoformat()
        self.audit_title: str = "Audit Sécurité Sprint 8 — NURU V12 Phase 1"

    # ── Ajout de findings ─────────────────────────────────────

    def add_finding(
        self,
        module: str,
        check: str,
        severity: str,
        status: str,
        description: str,
        recommendation: str = "",
    ) -> None:
        """Ajoute un finding à l'audit.

        Args:
            module: Module source.
            check: Nom du check.
            severity: CRITICAL, HIGH, MEDIUM, LOW, ou INFO.
            status: PASS, FAIL, ou FIXED.
            description: Description détaillée.
            recommendation: Recommandation (optionnelle).
        """
        if severity not in SeverityLevel.ALL:
            raise ValueError(
                f"Sévérité invalide: '{severity}'. "
                f"Doit être l'un de: {', '.join(SeverityLevel.ALL)}"
            )
        if status not in ("PASS", "FAIL", "FIXED"):
            raise ValueError(
                f"Statut invalide: '{status}'. Doit être PASS, FAIL ou FIXED."
            )

        self.findings.append(
            Finding(
                module=module,
                check=check,
                severity=severity,
                status=status,
                description=description,
                recommendation=recommendation,
            )
        )

    def add_corrective_action(
        self, module: str, description: str, files: list[str] | None = None
    ) -> None:
        """Ajoute une action corrective appliquée.

        Args:
            module: Module concerné.
            description: Description du correctif.
            files: Liste des fichiers modifiés.
        """
        self.corrective_actions.append(
            CorrectiveAction(
                module=module,
                description=description,
                files=files or [],
            )
        )

    # ── Statistiques ──────────────────────────────────────────

    @property
    def total(self) -> int:
        return len(self.findings)

    @property
    def passed(self) -> int:
        return sum(1 for f in self.findings if f.status == "PASS")

    @property
    def failed(self) -> int:
        return sum(1 for f in self.findings if f.status == "FAIL")

    @property
    def fixed(self) -> int:
        return sum(1 for f in self.findings if f.status == "FIXED")

    def by_severity(self, severity: str) -> list[Finding]:
        return [f for f in self.findings if f.severity == severity]

    @property
    def critical_count(self) -> int:
        return len(self.by_severity(SeverityLevel.CRITICAL))

    @property
    def high_count(self) -> int:
        return len(self.by_severity(SeverityLevel.HIGH))

    @property
    def medium_count(self) -> int:
        return len(self.by_severity(SeverityLevel.MEDIUM))

    @property
    def low_count(self) -> int:
        return len(self.by_severity(SeverityLevel.LOW))

    @property
    def info_count(self) -> int:
        return len(self.by_severity(SeverityLevel.INFO))

    # ── Génération de rapport ─────────────────────────────────

    def generate_report(self, fmt: str = "text") -> str:
        """Génère le rapport d'audit formaté.

        Args:
            fmt: Format de sortie ("text" ou "json").

        Returns:
            Rapport formaté en texte ou JSON.
        """
        if fmt == "json":
            return self._generate_json()

        return self._generate_text()

    def _generate_text(self) -> str:
        """Génère un rapport texte formaté."""
        lines = [
            "╔" + "═" * 68 + "╗",
            "║  RAPPORT D'AUDIT DE SÉCURITÉ".ljust(57)
            + f" {self.timestamp[:10]} ║",
            "║  " + self.audit_title.ljust(56) + "║",
            "╚" + "═" * 68 + "╝",
            "",
            "📊 STATISTIQUES",
            "─" * 50,
            f"  Total checks       : {self.total}",
            f"  ✅ PASS            : {self.passed}",
            f"  ❌ FAIL            : {self.failed}",
            f"  🔧 FIXED           : {self.fixed}",
            "",
            f"  🔴 CRITICAL        : {self.critical_count}",
            f"  🟠 HIGH            : {self.high_count}",
            f"  🟡 MEDIUM          : {self.medium_count}",
            f"  🟢 LOW             : {self.low_count}",
            f"  ℹ️ INFO            : {self.info_count}",
            "",
        ]

        # Findings détaillés
        if self.findings:
            lines.append("📋 FINDINGS DÉTAILLÉS")
            lines.append("─" * 50)
            lines.append("")

            sorted_findings = sorted(
                self.findings,
                key=lambda f: (
                    SeverityLevel.sort_key(f.severity),
                    f.module,
                    f.check,
                ),
            )

            for f in sorted_findings:
                status_icon = {
                    "PASS": "✅",
                    "FAIL": "❌",
                    "FIXED": "🔧",
                }.get(f.status, "❓")

                severity_tag = {
                    "CRITICAL": "🔴 CRITICAL",
                    "HIGH": "🟠 HIGH",
                    "MEDIUM": "🟡 MEDIUM",
                    "LOW": "🟢 LOW",
                    "INFO": "ℹ️ INFO",
                }.get(f.severity, f.severity)

                lines.append(f"  [{severity_tag}] {status_icon}")
                lines.append(f"  Module : {f.module}")
                lines.append(f"  Check  : {f.check}")
                lines.append(f"  Detail : {f.description}")
                if f.recommendation:
                    lines.append(f"  →      : {f.recommendation}")
                lines.append("")

        # Actions correctives
        if self.corrective_actions:
            lines.append("🔧 ACTIONS CORRECTIVES APPLIQUÉES")
            lines.append("─" * 50)
            lines.append("")

            for ca in self.corrective_actions:
                lines.append(f"  Module : {ca.module}")
                lines.append(f"  Action : {ca.description}")
                if ca.files:
                    lines.append("  Fichiers modifiés :")
                    for f in ca.files:
                        lines.append(f"    - {f}")
                lines.append("")

        # Résumé
        lines.append("📈 RÉSUMÉ")
        lines.append("─" * 50)
        if self.failed == 0:
            lines.append("  ✅ Tous les checks de sécurité sont PASS ou FIXED.")
            lines.append("  L'audit est conforme.")
        else:
            lines.append(
                f"  ❌ {self.failed} check(s) en échec nécessitent "
                f"une attention immédiate."
            )
        lines.append("")
        lines.append("═" * 70)
        lines.append(f"  Rapport généré le {self.timestamp}")
        lines.append("═" * 70)

        return "\n".join(lines)

    def _generate_json(self) -> str:
        """Génère un rapport au format JSON."""
        data = {
            "title": self.audit_title,
            "timestamp": self.timestamp,
            "statistics": {
                "total": self.total,
                "passed": self.passed,
                "failed": self.failed,
                "fixed": self.fixed,
                "by_severity": {
                    "critical": self.critical_count,
                    "high": self.high_count,
                    "medium": self.medium_count,
                    "low": self.low_count,
                    "info": self.info_count,
                },
            },
            "findings": [f.to_dict() for f in self.findings],
            "corrective_actions": [
                ca.to_dict() for ca in self.corrective_actions
            ],
        }
        return json.dumps(data, indent=2, ensure_ascii=False)

    def export_json(self, path: str) -> None:
        """Exporte le rapport en JSON vers un fichier.

        Args:
            path: Chemin du fichier de sortie.
        """
        with open(path, "w", encoding="utf-8") as f:
            f.write(self.generate_report(fmt="json"))

    def merge(self, other: AuditReport) -> None:
        """Fusionne les findings d'un autre rapport dans celui-ci.

        Args:
            other: Autre rapport AuditReport à fusionner.
        """
        self.findings.extend(other.findings)
        self.corrective_actions.extend(other.corrective_actions)


# ── Helper : generate_text_report ────────────────────────────────


def generate_report(
    findings: list[dict] | None = None,
    fix_summary: str | None = None,
) -> str:
    """Génère un rapport texte simple à partir de données brutes.

    Fonction utilitaire pour les cas où AuditReport n'est pas
    nécessaire.

    Args:
        findings: Liste de dicts avec clés module, check, severity,
                  status, description, recommendation.
        fix_summary: Résumé textuel des correctifs appliqués.

    Returns:
        Rapport texte formaté.
    """
    report = AuditReport()

    if findings:
        for f in findings:
            report.add_finding(
                module=f.get("module", "?"),
                check=f.get("check", "?"),
                severity=f.get("severity", "INFO"),
                status=f.get("status", "FAIL"),
                description=f.get("description", ""),
                recommendation=f.get("recommendation", ""),
            )

    if fix_summary:
        report.add_corrective_action(
            module="global",
            description=fix_summary,
        )

    return report.generate_report()


# ═══════════════════════════════════════════════════
# FICHIER: src/core/conversation_engine.py  (377 lignes)
# ═══════════════════════════════════════════════════

"""ConversationEngine — Pont UI ↔ Backend NURU (V12).

Bridge asynchrone entre les composants PySide6 (ConversationSurface,
NuruInputBar, NuruPresenceOrb) et le pipeline LLM (NuruOrchestrator).

Architecture :
  - Thread asyncio dédié pour le backend (pas de blocage UI)
  - Signaux PySide6 pour le streaming de tokens
  - Gestion d'état OrbState : IDLE → THINKING → SPEAKING → IDLE
  - Support multi-session

Usage :
  engine = ConversationEngine()
  engine.start()
  engine.send_message("Bonjour NURU")
"""

from __future__ import annotations

import asyncio
import logging
import threading
import time
from pathlib import Path
from typing import Optional

from PySide6.QtCore import QObject, Signal, QTimer

from src.nuru_core import NuruCore
from src.core.events import EventBus
from src.ui.presence_orb import OrbState

logger = logging.getLogger(__name__)


class ConversationEngine(QObject):
    """Bridge entre l'interface PySide6 et le pipeline asynchrone NURU.

    Émet des signaux thread-safe pour mettre à jour l'UI en temps réel
    pendant la génération des réponses.
    """

    # ── Signaux ──
    # Chaque token de réponse (streaming)
    token_received = Signal(str)
    # Signal de fin avec le texte complet
    response_complete = Signal(str)
    # Erreur survenue
    error_occurred = Signal(str, str)  # (code, message)
    # Changement d'état de l'orb
    state_changed = Signal(object)  # OrbState
    # Stratégie pipeline (routing / rag / generation / completed)
    strategy_changed = Signal(str)
    # Métadonnées de réponse (confidence, sources, durée, etc.)
    response_metadata = Signal(object)  # dict
    # Transcription vocale temps réel
    voice_transcript = Signal(str)
    # Session vocale terminée avec le texte final
    voice_session_end = Signal(str)

    def __init__(self, parent: QObject | None = None):
        super().__init__(parent)
        self._nuru: NuruCore | None = None
        self._loop: asyncio.AbstractEventLoop | None = None
        self._thread: threading.Thread | None = None
        self._ready = False
        self._current_session: str = "default"
        self._processing = False
        # Cache de session pour réutilisation
        self._sessions: dict[str, str] = {}
        # Évite de surcharger les signaux pendant le démarrage
        self._started = False
        self._voice_running = False
        self._voice_buffer: list[str] = []

    # ── Cycle de vie ──

    def start(self) -> None:
        """Initialise NuruCore dans le thread asyncio (pas de blocage UI)."""
        if self._started:
            logger.warning("ConversationEngine déjà démarré")
            return

        logger.info("🚀 ConversationEngine — démarrage thread asyncio...")
        self.state_changed.emit(OrbState.THINKING)

        # V16 FIX : Créer le thread asyncio AVANT NuruCore pour éviter
        # le blocage de l'UI (15-20s de freeze). NuruCore est construit
        # dans _init_async sur le thread asyncio dédié.
        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(
            target=self._run_async_loop,
            name="nuru-asyncio",
            daemon=True,
        )
        self._thread.start()

        # Construire NuruCore dans le thread asyncio
        future = asyncio.run_coroutine_threadsafe(
            self._init_async(),
            self._loop,
        )
        future.add_done_callback(self._on_init_done)

    def _run_async_loop(self) -> None:
        """Boucle asyncio du thread dédié."""
        asyncio.set_event_loop(self._loop)
        self._loop.run_forever()

    async def _init_async(self) -> None:
        """Construit NuruCore et démarre les tâches background (thread asyncio)."""
        try:
            self._nuru = NuruCore()
            logger.info("✅ NuruCore initialisé dans le thread asyncio")
            self._nuru.start_background_tasks()
            logger.info("✅ Tâches background NuruCore démarrées")
        except Exception as e:
            logger.error(f"⚠️ Échec NuruCore asynchrone: {e}")
            raise

    def _on_init_done(self, future: asyncio.Future) -> None:
        """Callback quand l'init asynchrone est terminée."""
        try:
            future.result()
            self._ready = True
            self._started = True
            self.state_changed.emit(OrbState.IDLE)
            logger.info("✅ ConversationEngine prêt")
        except Exception as e:
            logger.error(f"❌ Échec init asynchrone: {e}")
            self.error_occurred.emit("async_init", str(e))
            self.state_changed.emit(OrbState.ERROR)

    def stop(self) -> None:
        """Arrête la boucle asyncio et libère les ressources."""
        if self._loop and self._loop.is_running():
            self._loop.call_soon_threadsafe(self._loop.stop)
        self._started = False
        self._ready = False
        logger.info("🛑 ConversationEngine arrêté")

    # ── API publique ──

    @property
    def is_ready(self) -> bool:
        return self._ready

    @property
    def is_processing(self) -> bool:
        return self._processing

    @property
    def session_id(self) -> str:
        return self._current_session

    @property
    def nuru(self) -> NuruCore | None:
        """Accès au backend NuruCore (services mémoire, RAG, etc.)."""
        return self._nuru

    @property
    def memory_store(self):
        """MemoryStore du backend."""
        return self._nuru.memory if self._nuru else None

    @property
    def rag_engine(self):
        """RAGEngine du backend."""
        return self._nuru.rag if self._nuru else None

    @property
    def orchestrator(self):
        """NuruOrchestrator du backend."""
        return self._nuru.orchestrator if self._nuru else None

    @property
    def model_router(self):
        """ModelRouter du backend."""
        return self._nuru.model_router if hasattr(self._nuru, 'model_router') and self._nuru else None

    @property
    def mcp_client(self):
        """MCPClient pour outils externes."""
        return self._nuru.mcp_client if hasattr(self._nuru, 'mcp_client') and self._nuru else None

    @property
    def mcp_server(self):
        """MCPServer exposant les outils internes."""
        return self._nuru.mcp_server if hasattr(self._nuru, 'mcp_server') and self._nuru else None

    @property
    def proactive_engine(self):
        """ProactiveEngine pour agents et routines."""
        return self._nuru.proactive if hasattr(self._nuru, 'proactive') and self._nuru else None

    @property
    def routine_scheduler(self):
        """RoutineScheduler pour tâches planifiées."""
        return self._nuru.routines if hasattr(self._nuru, 'routines') and self._nuru else None

    @property
    def current_model_name(self) -> str:
        """Nom du modèle actif."""
        if self._nuru and hasattr(self._nuru, 'config'):
            return getattr(self._nuru.config, 'model', getattr(self._nuru.config, 'local_model', 'qwen2.5:3b'))
        return "qwen2.5:3b"

    @property
    def current_provider(self) -> str:
        """Fournisseur actif."""
        if self._nuru and hasattr(self._nuru, 'config'):
            return getattr(self._nuru.config, 'provider', getattr(self._nuru.config, 'mode', 'local'))
        return "local"

    def new_session(self, session_id: str | None = None) -> str:
        """Crée ou bascule vers une nouvelle session."""
        sid = session_id or f"session_{int(time.time())}"
        self._current_session = sid
        self._sessions[sid] = sid
        return sid

    def send_message(self, text: str) -> None:
        """Point d'entrée principal : envoie un message au backend.

        Peut être appelé depuis n'importe quel thread (Qt ou non).
        La réponse arrive via les signaux token_received / response_complete.
        """
        if not text or not text.strip():
            return
        if not self._ready:
            logger.warning("ConversationEngine pas encore prêt")
            self.error_occurred.emit("not_ready", "Le moteur NURU n'est pas encore prêt")
            return
        if self._processing:
            logger.warning("Déjà en train de traiter — message ignoré")
            self.error_occurred.emit("busy", "NURU est déjà en train de répondre")
            return

        self._processing = True
        self._safe_emit(self.state_changed, OrbState.THINKING)

        # Lancer le traitement dans le thread asyncio
        asyncio.run_coroutine_threadsafe(
            self._process(text),
            self._loop,
        )

    # ── Voice ──

    def start_voice_session(self) -> None:
        """Démarre la capture micro + STT dans le thread asyncio."""
        if not self._ready or not self._loop:
            return
        self.state_changed.emit(OrbState.LISTENING)
        self._voice_running = True
        self._voice_buffer: list[str] = []
        asyncio.run_coroutine_threadsafe(
            self._run_voice_capture(),
            self._loop,
        )
        logger.info("🎤 Session vocale démarrée")

    def stop_voice_session(self, final_text: str = "") -> None:
        """Arrête la capture micro."""
        self._voice_running = False
        self.state_changed.emit(OrbState.IDLE)
        if final_text.strip():
            self.voice_session_end.emit(final_text)
        logger.info("🎤 Session vocale terminée")

    async def _run_voice_capture(self) -> None:
        """Async generator : capture micro → VAD → STT → signaux UI."""
        audio = self._nuru.audio
        try:
            async for chunk, is_speech in audio.capture_mic():
                if not self._voice_running:
                    break
                if is_speech and chunk is not None:
                    # Écrire le chunk dans un buffer audio
                    audio_path = Path(f"/tmp/nuru_voice_{int(time.time())}.wav")
                    import soundfile as sf
                    sf.write(audio_path, chunk, 16000)
                    # Transcrire
                    text = await audio.transcribe(audio_path)
                    if text.strip():
                        self._voice_buffer.append(text)
                        self._safe_emit(self.voice_transcript, text)
                    # Nettoyer
                    try:
                        audio_path.unlink()
                    except OSError:
                        pass
                # Petite pause pour ne pas saturer
                await asyncio.sleep(0.1)
        except Exception as e:
            logger.error(f"🎤 Erreur capture vocale: {e}")
        finally:
            logger.info("🎤 Capture vocale terminée")

    # ── Traitement interne ──

    async def _process(self, text: str) -> None:
        """Exécute le pipeline complet dans le thread asyncio.

        Yields tokens → émet signaux thread-safe vers l'UI.
        """
        full_response = ""
        first_token = True
        # Stockage des métadonnées reçues via EventBus
        _metadata: dict = {}

        # S'abonner aux étapes du pipeline EventBus
        def _on_pipeline_step(data):
            step = data.get("step", "thinking") if isinstance(data, dict) else "thinking"
            self._safe_emit(self.strategy_changed, step)

        # S'abonner aux métadonnées de fin de génération
        def _on_generation_complete(data):
            nonlocal _metadata
            if isinstance(data, dict):
                _metadata = data

        bus = EventBus()
        bus.subscribe("pipeline.step", _on_pipeline_step)
        bus.subscribe("generation_complete", _on_generation_complete)

        # Émettre l'état initial "routing"
        self._safe_emit(self.strategy_changed, "routing")

        try:
            async for token in self._nuru.orchestrator.process_query(
                text,
                session_id=self._current_session,
            ):
                full_response += token
                self._safe_emit(self.token_received, token)
                if first_token:
                    first_token = False
                    self._safe_emit(self.strategy_changed, "generation")

            # Finalisation
            self._safe_emit(self.strategy_changed, "completed")
            self._safe_emit(self.response_metadata, _metadata)
            self._safe_emit(self.response_complete, full_response)
            self._safe_emit(self.state_changed, OrbState.IDLE)

        except asyncio.CancelledError:
            logger.info("Requête annulée")
            self._safe_emit(self.state_changed, OrbState.IDLE)

        except Exception as e:
            logger.error(f"❌ Erreur traitement: {e}", exc_info=True)
            self._safe_emit(self.error_occurred, "processing", str(e))
            self._safe_emit(self.state_changed, OrbState.ERROR)

        finally:
            bus.unsubscribe("pipeline.step", _on_pipeline_step)
            bus.unsubscribe("generation_complete", _on_generation_complete)
            self._processing = False

    # ── Helpers ──

    def _safe_emit(self, signal, value) -> None:
        """Émet un signal PySide6 depuis n'importe quel thread.
        
        V16 AUDIT FIX QW10 (v2) : utilise QTimer.singleShot avec fermeture
        Python au lieu de QMetaObject.invokeMethod (qui ne peut pas marshaller
        des objets Signal + valeur Python arbitraire à travers le système de
        types Qt).
        """
        if threading.current_thread() is not threading.main_thread():
            # Marshaling vers le thread Qt principal via QTimer (closure Python)
            from PySide6.QtCore import QTimer
            QTimer.singleShot(0, lambda: signal.emit(value))
        else:
            signal.emit(value)


