"""
NURU V6 — Extracteur CV → JSON structuré (Pydantic).

Pipeline d'extraction LLM qui transforme un CV textuel brut en JSON structuré
avant indexation. Solution au problème : un CV est une base de données
relationnelle (Candidat → Expériences → Rôles → Réalisations), pas du
texte plat approprié pour du chunking vectoriel.

Usage:
    from src.cv_extractor import extract_cv, is_cv
    cv = await extract_cv(text, filename="mon_cv.pdf")
    if cv:
        print(cv.model_dump_json(indent=2))
"""

import re
import json
import logging
from typing import Optional
from dataclasses import dataclass, field
from datetime import datetime

logger = logging.getLogger(__name__)

# ── Détection de CV par nom de fichier ──
# Patterns séparés car \b (word boundary) ne fonctionne pas avec underscore
CV_WORD_PATTERNS = re.compile(
    r'(?:^|[\s_\-/])(cv|curriculum|vitae|resume|profil|motivation|'
    r'lettre|candidature|cover|biographie|biography|career)'
    r'(?:$|[\s_\-\.])',
    re.IGNORECASE,
)
# Détection renforcée : CV en début/présence dans le nom
CV_NAIVE_PATTERN = re.compile(r'[_-]cv|cv[_-]', re.IGNORECASE)

# Indices textuels qui signalent un CV dans le contenu
CV_CONTENT_SIGNALS = re.compile(
    r'(expérience professionnelle|professional experience|'
    r'formation|education|diplôme|degree|compétence|skill|'
    r'résumé professionnel|career summary|profil professionnel|'
    r'poste actuel|current position|employeur|employer|'
    r'références|references|langues|languages|'
    r'mission|réalisation|achievement|'
    r'curriculum vitae)',
    re.IGNORECASE,
)


def is_cv(fname: str) -> bool:
    """Détecte si un nom de fichier correspond à un CV/document de profil.

    Utilise les mêmes patterns que le HierarchicalChunkerV2 pour la cohérence.
    """
    return bool(CV_WORD_PATTERNS.search(fname)) or bool(CV_NAIVE_PATTERN.search(fname))


def is_cv_content(text: str) -> bool:
    """Détection renforcée : vérifie si le contenu ressemble à un CV.

    Utile quand le nom de fichier n'est pas évident.
    """
    # Un CV a généralement plusieurs sections clairement identifiables
    signals = CV_CONTENT_SIGNALS.findall(text[:5000])
    return len(signals) >= 3


# ── Pydantic-like models (dataclasses pour éviter dépendance pydantic) ──

@dataclass
class Experience:
    entreprise: str = ""
    poste: str = ""
    dates: str = ""
    realisations: list[str] = field(default_factory=list)
    lieu: str = ""

    def to_dict(self) -> dict:
        return {
            "entreprise": self.entreprise,
            "poste": self.poste,
            "dates": self.dates,
            "lieu": self.lieu,
            "realisations": self.realisations,
        }


@dataclass
class Formation:
    diplome: str = ""
    etablissement: str = ""
    dates: str = ""
    mention: str = ""

    def to_dict(self) -> dict:
        return {
            "diplome": self.diplome,
            "etablissement": self.etablissement,
            "dates": self.dates,
            "mention": self.mention,
        }


@dataclass
class Competence:
    domaine: str = ""
    items: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "domaine": self.domaine,
            "items": self.items,
        }


@dataclass
class CVStructure:
    nom: str = ""
    titre_poste: str = ""
    resume_global: str = ""
    experiences: list[Experience] = field(default_factory=list)
    formations: list[Formation] = field(default_factory=list)
    competences: list[Competence] = field(default_factory=list)
    langues: list[str] = field(default_factory=list)
    certifications: list[str] = field(default_factory=list)
    coordonnees: dict = field(default_factory=dict)
    source_file: str = ""

    def to_dict(self) -> dict:
        return {
            "nom": self.nom,
            "titre_poste": self.titre_poste,
            "resume_global": self.resume_global,
            "experiences": [e.to_dict() for e in self.experiences],
            "formations": [f.to_dict() for f in self.formations],
            "competences": [c.to_dict() for c in self.competences],
            "langues": self.langues,
            "certifications": self.certifications,
            "coordonnees": self.coordonnees,
            "source_file": self.source_file,
        }

    def model_dump_json(self, indent: int = 2) -> str:
        """Sérialisation JSON pour le stockage en DB."""
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)

    @classmethod
    def from_json(cls, json_str: str, source_file: str = "") -> Optional["CVStructure"]:
        """Reconstruit un CVStructure depuis son JSON stocké."""
        try:
            data = json.loads(json_str)
            data["source_file"] = source_file

            experiences = [
                Experience(**e) for e in data.get("experiences", [])
            ]
            formations = [
                Formation(**f) for f in data.get("formations", [])
            ]
            competences = [
                Competence(**c) for c in data.get("competences", [])
            ]

            return cls(
                nom=data.get("nom", ""),
                titre_poste=data.get("titre_poste", ""),
                resume_global=data.get("resume_global", ""),
                experiences=experiences,
                formations=formations,
                competences=competences,
                langues=data.get("langues", []),
                certifications=data.get("certifications", []),
                coordonnees=data.get("coordonnees", {}),
                source_file=source_file,
            )
        except (json.JSONDecodeError, TypeError, KeyError) as e:
            logger.error(f"Erreur parsing JSON CV: {e}")
            return None


# ── Prompt d'extraction structurée ──

EXTRACTION_SYSTEM_PROMPT = """Tu es un extracteur de CV spécialisé. Tu reçois le texte brut d'un CV et tu dois en extraire les informations structurées au format JSON.

Règles strictes :
1. Extrais UNIQUEMENT les informations présentes dans le texte fourni.
2. N'invente JAMAIS des informations absentes.
3. Si une information est incertaine, laisse le champ vide ("" ou []).
4. Sois exhaustif : extrais TOUTES les expériences, formations, compétences.
5. Pour les dates, conserve le format original (ex: "2018-2021", "Mars 2019").
6. Chaque réalisation doit être une phrase complète extraite textuellement.

Format de sortie JSON (à produire STRICTEMENT) :
{
    "nom": "Nom complet",
    "titre_poste": "Titre du poste actuel ou recherché",
    "resume_global": "Résumé du profil en 1-2 phrases",
    "experiences": [
        {
            "entreprise": "Nom de l'entreprise",
            "poste": "Titre du poste",
            "dates": "Période",
            "lieu": "Ville, Pays",
            "realisations": ["Réalisation 1", "Réalisation 2"]
        }
    ],
    "formations": [
        {
            "diplome": "Intitulé du diplôme",
            "etablissement": "Nom de l'établissement",
            "dates": "Année d'obtention",
            "mention": "Mention (ou vide)"
        }
    ],
    "competences": [
        {
            "domaine": "Domaine (Informatique, Management, etc.)",
            "items": ["Compétence 1", "Compétence 2"]
        }
    ],
    "langues": ["Langue 1 (Niveau)", "Langue 2 (Niveau)"],
    "certifications": ["Certification 1", "Certification 2"],
    "coordonnees": {
        "email": "",
        "telephone": "",
        "ville": "",
        "linkedin": ""
    }
}

Produis UNIQUEMENT le JSON, sans commentaires ni texte autour."""


def _extract_json_from_response(text: str) -> Optional[dict]:
    """Extrait un bloc JSON valide depuis la réponse du LLM.

    Gère les cas où le LLM ajoute du texte autour du JSON.
    """
    # Essayer de trouver un bloc ```json ... ```
    json_match = re.search(r'```(?:json)?\s*\n?(.*?)\n?```', text, re.DOTALL)
    if json_match:
        try:
            return json.loads(json_match.group(1))
        except json.JSONDecodeError:
            pass

    # Essayer de trouver { ... } directement
    brace_match = re.search(r'\{.*\}', text, re.DOTALL)
    if brace_match:
        try:
            return json.loads(brace_match.group(0))
        except json.JSONDecodeError:
            pass

    return None


async def extract_cv_local(text: str, filename: str = "") -> Optional[CVStructure]:
    """Extraction via LLM local (Phi-4-mini / Qwen 1.5B).

    Utilise mlx_lm.generate pour une extraction non-streaming.
    Bascule MLX en CPU pour éviter GPU timeout sur M1 8 Go saturé.
    """
    try:
        import mlx.core as mx
        from mlx_lm import load, generate

        from src.config import config

        # V15: RAM guard — skip local extraction si mémoire insuffisante
        import psutil
        available_gb = psutil.virtual_memory().available / (1024**3)
        if available_gb < 1.0:
            logger.warning(f"RAM insuffisante pour extraction CV ({available_gb:.1f} Go), skip local")
            return None

        # Token tronqué si trop long pour le modèle local (1.5B/4B)
        max_chars = 12000  # ~3000 tokens pour le contexte local
        if len(text) > max_chars:
            logger.info(f"CV tronqué de {len(text)} → {max_chars} caractères pour extraction locale")
            text = text[:max_chars]

        prompt = f"[INST] {EXTRACTION_SYSTEM_PROMPT}\n\nTexte du CV :\n{text}\n\n[/INST]"

        model_id = config.local_model
        resolved_path = config.get_model_path(model_id)

        logger.info(f"Extraction CV locale avec {model_id}...")

        # V15: basculer MLX en CPU pour éviter GPU timeout Metal
        # (l'extraction de CV est un batch background, la lenteur CPU est acceptable)
        original_device = mx.default_device()
        mx.set_default_device(mx.cpu)
        logger.info("MLX basculé en CPU pour l'extraction CV")

        try:
            model, tokenizer = load(resolved_path)

            response = generate(
                model, tokenizer,
                prompt=prompt,
                max_tokens=1500,
            )
        finally:
            # Restaurer le device GPU après extraction
            mx.set_default_device(original_device)
            logger.info("MLX restauré en GPU")

        data = _extract_json_from_response(response)
        if data:
            cv = _build_cv_structure(data, filename)
            logger.info(f"✅ CV extrait localement : {cv.nom or 'inconnu'} "
                        f"({len(cv.experiences)} expériences)")
            return cv

        logger.warning("Échec extraction JSON depuis réponse locale")
        return None

    except ImportError as e:
        logger.error(f"mlx_lm non disponible : {e}")
        return None
    except Exception as e:
        logger.error(f"Erreur extraction CV locale : {e}")
        return None


async def extract_cv_cloud(text: str, filename: str = "") -> Optional[CVStructure]:
    """Extraction via LLM cloud (OpenCode Zen, Groq, DeepSeek, OpenRouter).

    Plus fiable que le local pour l'extraction structurée.
    """
    try:
        import httpx

        from src.config import config

        # Déterminer URL et clé selon le provider configuré
        provider = config.cloud_provider
        if provider == "groq":
            api_key = config.groq_key
            url = "https://api.groq.com/openai/v1/chat/completions"
            model = "llama-3.1-8b-instant"
        elif provider == "opencode_zen":
            api_key = config.opencode_zen_key
            if not api_key:
                logger.error("Clé OpenCode Zen non disponible pour extraction CV")
                return None
            url = config.opencode_zen_base_url + "/chat/completions"
            model = config.cloud_model
        elif provider == "deepseek":
            api_key = config.deepseek_key
            url = "https://api.deepseek.com/v1/chat/completions"
            model = "deepseek-chat"
        elif provider == "openrouter":
            api_key = config.openrouter_key
            url = "https://openrouter.ai/api/v1/chat/completions"
            model = config.cloud_model
        else:
            logger.warning(f"Provider cloud non supporté: {provider}")
            return None

        if not api_key:
            logger.warning(f"Clé API manquante pour {provider}")
            return None

        # Troncature pour respecter la fenêtre de contexte cloud
        max_chars = 24000  # ~6000 tokens
        if len(text) > max_chars:
            text = text[:max_chars]

        # V17: max_tokens adapté au provider (modèles reasoning nécessitent plus)
        extraction_max_tokens = 3000 if provider == "opencode_zen" else 2000

        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": model,
            "messages": [
                {"role": "system", "content": EXTRACTION_SYSTEM_PROMPT},
                {"role": "user", "content": f"Texte du CV :\n{text}"},
            ],
            "temperature": 0.1,
            "max_tokens": extraction_max_tokens,
            "response_format": {"type": "json_object"},
        }

        logger.info(f"Extraction CV via {provider} ({model})...")
        async with httpx.AsyncClient(timeout=60.0) as client:
            response = await client.post(url, headers=headers, json=payload)
            response.raise_for_status()
            result = response.json()

        content = result["choices"][0]["message"]["content"]

        # Essayer JSON direct, puis fallback regex
        data = None
        try:
            data = json.loads(content)
        except json.JSONDecodeError:
            data = _extract_json_from_response(content)

        if not data:
            logger.warning(f"Impossible d'extraire le JSON de la réponse {provider}")
            return None

        cv = _build_cv_structure(data, filename)
        logger.info(f"✅ CV extrait cloud : {cv.nom or 'inconnu'} "
                    f"({len(cv.experiences)} expériences, {len(cv.competences)} domaines)")
        return cv

    except ImportError as e:
        logger.error(f"httpx non disponible : {e}")
        return None
    except json.JSONDecodeError as e:
        logger.error(f"JSON invalide depuis {provider} (fallback échoué) : {e}")
        return None
    except Exception as e:
        logger.error(f"Erreur extraction CV cloud ({provider}): {e}")
        return None


def _build_cv_structure(data: dict, filename: str = "") -> CVStructure:
    """Construit un CVStructure à partir d'un dict JSON.

    Gère les imprécisions du LLM (noms de champs variés).
    """
    # Mapping des noms de champs possibles (le LLM peut varier)
    nom = (data.get("nom") or data.get("name") or data.get("full_name")
           or data.get("candidat") or data.get("candidate") or "")
    titre = (data.get("titre_poste") or data.get("poste_actuel")
             or data.get("current_position") or data.get("title") or "")
    resume = (data.get("resume_global") or data.get("profil")
              or data.get("summary") or data.get("profile") or "")

    experiences_raw = (data.get("experiences") or data.get("experience")
                       or data.get("experiences_professionnelles")
                       or data.get("work_experience") or [])

    formations_raw = (data.get("formations") or data.get("formation")
                      or data.get("education") or [])

    competences_raw = (data.get("competences") or data.get("competences_cles")
                       or data.get("skills") or data.get("competences_techniques")
                       or [])

    langues = (data.get("langues") or data.get("languages") or [])
    certifications = (data.get("certifications") or data.get("certification") or [])
    coordonnees = (data.get("coordonnees") or data.get("coordonnées")
                   or data.get("contact") or {})

    # Construire les objets typés
    experiences = []
    for e in experiences_raw:
        if isinstance(e, dict):
            experiences.append(Experience(
                entreprise=e.get("entreprise") or e.get("company") or e.get("employeur") or "",
                poste=e.get("poste") or e.get("title") or e.get("role") or "",
                dates=e.get("dates") or e.get("periode") or e.get("date") or "",
                lieu=e.get("lieu") or e.get("location") or "",
                realisations=e.get("realisations") or e.get("achievements")
                         or e.get("responsibilities") or [],
            ))

    formations = []
    for f in formations_raw:
        if isinstance(f, dict):
            formations.append(Formation(
                diplome=f.get("diplome") or f.get("degree") or f.get("diploma") or "",
                etablissement=f.get("etablissement") or f.get("school")
                             or f.get("institution") or f.get("university") or "",
                dates=f.get("dates") or f.get("year") or f.get("annee") or "",
                mention=f.get("mention") or f.get("grade") or "",
            ))

    competences = []
    for c in competences_raw:
        if isinstance(c, dict):
            competences.append(Competence(
                domaine=c.get("domaine") or c.get("category") or c.get("area") or "",
                items=c.get("items") or c.get("competences") or c.get("skills") or [],
            ))
        elif isinstance(c, str):
            # Cas simple : juste une liste de compétences sans catégorie
            competences.append(Competence(domaine="Général", items=[c]))

    return CVStructure(
        nom=nom,
        titre_poste=titre,
        resume_global=resume,
        experiences=experiences,
        formations=formations,
        competences=competences,
        langues=langues if isinstance(langues, list) else [],
        certifications=certifications if isinstance(certifications, list) else [],
        coordonnees=coordonnees if isinstance(coordonnees, dict) else {},
        source_file=filename,
    )


async def extract_cv(text: str, filename: str = "", prefer_cloud: bool = True) -> Optional[CVStructure]:
    """Point d'entrée principal : extraction CV avec fallback.

    Stratégie :
    1. Cloud (Groq) — plus fiable, JSON structuré garanti
    2. Local (Phi-4-mini/Qwen) — fallback si pas de cloud
    """
    if prefer_cloud:
        cv = await extract_cv_cloud(text, filename)
        if cv:
            return cv
        logger.info("Cloud indisponible, tentative locale...")

    cv = await extract_cv_local(text, filename)
    return cv


def format_cv_for_context(cv: CVStructure) -> str:
    """Formate un CV structuré en texte lisible pour injection dans le contexte RAG.

    Produit un format clair et complet que le LLM peut exploiter facilement.
    """
    parts = []
    parts.append(f"=== CV : {cv.nom} ===")
    if cv.titre_poste:
        parts.append(f"Poste : {cv.titre_poste}")
    if cv.resume_global:
        parts.append(f"Résumé : {cv.resume_global}")

    if cv.experiences:
        parts.append("\nExpériences professionnelles :")
        for exp in cv.experiences:
            parts.append(f"• {exp.poste} @ {exp.entreprise} ({exp.dates})")
            if exp.lieu:
                parts.append(f"  Lieu : {exp.lieu}")
            for r in exp.realisations:
                parts.append(f"  - {r}")

    if cv.formations:
        parts.append("\nFormation :")
        for f in cv.formations:
            line = f"• {f.diplome} - {f.etablissement} ({f.dates})"
            if f.mention:
                line += f" — {f.mention}"
            parts.append(line)

    if cv.competences:
        parts.append("\nCompétences :")
        for comp in cv.competences:
            items = ", ".join(comp.items)
            parts.append(f"• {comp.domaine} : {items}")

    if cv.langues:
        parts.append(f"\nLangues : {', '.join(cv.langues)}")

    if cv.certifications:
        parts.append(f"\nCertifications : {', '.join(cv.certifications)}")

    if cv.coordonnees:
        coords = []
        for k, v in cv.coordonnees.items():
            if v:
                coords.append(f"{k}: {v}")
        if coords:
            parts.append(f"\nContact : {' | '.join(coords)}")

    return "\n".join(parts)


# ═══════════════════════════════════════════════════
# FICHIER: src/document_extractor.py  (373 lignes)
# ═══════════════════════════════════════════════════

"""
NURU V6 — Extracteur universel de documents structurés (LLM).

Pour chaque document indexé (CV, rapport, lettre, article, note, etc.),
on extrait une fiche structurée : type, titre, résumé, sujets, entités.

Cela remplace le résumé extractif basique (premières lignes) par un
résumé LLM de qualité, stocké dans une table SQLite `doc_structured`
accessible par le RAG lors des requêtes pertinentes.

Usage:
    from src.document_extractor import extract_document, detect_doc_type
    meta = await extract_document(text, "rapport_riz_2024.pdf")
    print(meta.summary)
    print(meta.key_topics)
"""
import re
import json
import logging
from dataclasses import dataclass, field
from typing import Optional

logger = logging.getLogger(__name__)

# ── Détection du type de document ──
# Patterns avec \b pour les mots isolés + détection naive pour underscores
DOC_TYPE_PATTERNS = {
    "CV": re.compile(
        r'(?:^|[\s_\-/])(cv|curriculum|vitae|resume|career)(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "lettre_motivation": re.compile(
        r'(?:^|[\s_\-/])(motivation|candidature|cover)(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "rapport": re.compile(
        r'(?:^|[\s_\-/])(rapport|report|analyse|étude|analysis|survey|baseline|assessment|'
        r'review)(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "article": re.compile(
        r'(?:^|[\s_\-/])(article|publication|paper|journal|revue|newsletter)'
        r'(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "note": re.compile(
        r'(?:^|[\s_\-/])(note|notes|memo|meeting|réunion|summary)'
        r'(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "presentation": re.compile(
        r'(?:^|[\s_\-/])(presentation|slide|deck|ppt|powerpoint|présentation|'
        r'exposé)(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "technique": re.compile(
        r'(?:^|[\s_\-/])(guide|tutorial|manuel|documentation|spec|spécification|'
        r'technical)(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
    "formulaire": re.compile(
        r'(?:^|[\s_\-/])(formulaire|form|questionnaire|survey|application)'
        r'(?:$|[\s_\-\.\d])',
        re.IGNORECASE,
    ),
}

# Détection naive pour underscores (ex: mon_cv.pdf, cv_anglais.pdf)
DOC_TYPE_NAIVE = {
    "CV": re.compile(r'[_-]cv|cv[_-]|profil|lettre_motivation|cover_letter', re.IGNORECASE),
    "rapport": re.compile(r'rapport_|_rapport', re.IGNORECASE),
    "note": re.compile(r'note_|_note|compte_rendu|compte-rendu', re.IGNORECASE),
}


def detect_doc_type(filename: str, text: str = "") -> str:
    """Détecte le type de document par le nom de fichier puis le contenu."""
    combined = filename
    if text:
        combined += " " + text[:2000]

    for doc_type, pattern in DOC_TYPE_PATTERNS.items():
        if pattern.search(combined):
            return doc_type

    for doc_type, pattern in DOC_TYPE_NAIVE.items():
        if pattern.search(filename):
            return doc_type

    return "document"


# ── Modèle de métadonnées universel ──

@dataclass
class DocumentMetadata:
    """Métadonnées structurées pour n'importe quel document."""
    source_file: str = ""
    doc_type: str = "document"
    title: str = ""
    summary: str = ""
    key_topics: list[str] = field(default_factory=list)
    entities: list[str] = field(default_factory=list)  # personnes, organisations
    dates_mentioned: list[str] = field(default_factory=list)
    language: str = ""
    word_count: int = 0
    structured_json: str = ""  # JSON complet pour stockage

    def to_dict(self) -> dict:
        return {
            "doc_type": self.doc_type,
            "title": self.title,
            "summary": self.summary,
            "key_topics": self.key_topics,
            "entities": self.entities,
            "dates_mentioned": self.dates_mentioned,
            "language": self.language,
            "word_count": self.word_count,
        }

    def model_dump_json(self, indent: int = 2) -> str:
        """Sérialisation pour stockage en DB."""
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)

    def format_for_context(self) -> str:
        """Formate les métadonnées en texte lisible pour injection RAG."""
        lines = [f"=== FICHE : {self.title or self.source_file} ==="]
        lines.append(f"Type : {self.doc_type}")
        if self.summary:
            lines.append(f"Résumé : {self.summary}")
        if self.key_topics:
            lines.append(f"Sujets : {', '.join(self.key_topics)}")
        if self.entities:
            lines.append(f"Entités : {', '.join(self.entities)}")
        if self.dates_mentioned:
            lines.append(f"Dates : {', '.join(self.dates_mentioned)}")
        if self.language:
            lines.append(f"Langue : {self.language}")
        lines.append(f"Mots : {self.word_count}")
        return "\n".join(lines)


# ── Prompt d'extraction générique ──

GENERIC_EXTRACTION_PROMPT = """Tu es un extracteur de métadonnées de documents. Tu reçois le texte brut d'un document et tu dois en extraire les informations structurées au format JSON.

Règles strictes :
1. Extrais UNIQUEMENT les informations présentes dans le texte.
2. N'invente JAMAIS des informations absentes. Laisse les champs vides si incertain.
3. Sois concis : résumé en 2-3 phrases max, sujets en 3-5 mots-clés max.

Format JSON à produire STRICTEMENT :
{
    "title": "Titre du document (ou première phrase significative)",
    "summary": "Résumé du document en 2-3 phrases",
    "key_topics": ["Sujet 1", "Sujet 2", "Sujet 3"],
    "entities": ["Personne ou organisation mentionnée"],
    "dates_mentioned": ["Date ou période mentionnée"],
    "language": "Français|Anglais|... (langue principale du document)"
}

Produis UNIQUEMENT le JSON, sans commentaires."""


EXTRACTION_SYSTEM_PROMPT = """Tu es un assistant spécialisé dans l'extraction de métadonnées de documents.
Pour chaque document, tu dois identifier :
- Le TITRE : le titre exact ou déduit
- Le RÉSUMÉ : 2-3 phrases qui capturent l'essentiel
- Les SUJETS CLÉS : 3-5 mots-clés ou thèmes principaux
- Les ENTITÉS : personnes, organisations, lieux mentionnés
- Les DATES : dates ou périodes clés mentionnées
- La LANGUE : langue principale du document

Sois précis et concis. Ne fabrique jamais d'informations absentes."""


def _extract_json(text: str) -> Optional[dict]:
    """Extrait un bloc JSON de la réponse du LLM."""
    # Essayer bloc ```json ... ```
    m = re.search(r'```(?:json)?\s*\n?(.*?)\n?```', text, re.DOTALL)
    if m:
        try:
            return json.loads(m.group(1))
        except json.JSONDecodeError:
            pass
    # Essayer { ... }
    m = re.search(r'\{.*\}', text, re.DOTALL)
    if m:
        try:
            return json.loads(m.group(0))
        except json.JSONDecodeError:
            pass
    return None


async def extract_generic_cloud(text: str, filename: str = "") -> Optional[DocumentMetadata]:
    """Extraction générique via LLM Cloud — utilise le provider configuré (OpenCode Zen, Groq, etc.)."""
    try:
        import httpx
        import asyncio
        from src.config import config

        # Déterminer URL et clé selon le provider configuré
        provider = config.cloud_provider
        if provider == "groq":
            api_key = config.groq_key
            url = "https://api.groq.com/openai/v1/chat/completions"
            model = "llama-3.1-8b-instant"
        elif provider == "opencode_zen":
            api_key = config.opencode_zen_key
            if not api_key:
                logger.warning("Clé OpenCode Zen non disponible pour extraction générique")
                return None
            url = config.opencode_zen_base_url + "/chat/completions"
            model = config.cloud_model
        elif provider == "deepseek":
            api_key = config.deepseek_key
            url = "https://api.deepseek.com/v1/chat/completions"
            model = "deepseek-chat"
        elif provider == "openrouter":
            api_key = config.openrouter_key
            url = "https://openrouter.ai/api/v1/chat/completions"
            model = config.cloud_model
        else:
            logger.warning(f"Provider cloud non supporté pour extraction: {provider}")
            return None

        if not api_key:
            logger.warning(f"Clé API manquante pour {provider}")
            return None

        # Troncature pour la fenêtre cloud
        max_chars = 20000
        if len(text) > max_chars:
            text = text[:max_chars]

        # V17: max_tokens adapté au provider (modèles reasoning nécessitent plus)
        extraction_max_tokens = 2000 if provider == "opencode_zen" else 800

        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": model,
            "messages": [
                {"role": "system", "content": EXTRACTION_SYSTEM_PROMPT
                 + "\n\nFormat JSON attendu : {\"title\": str, \"summary\": str, "
                 "\"key_topics\": [str], \"entities\": [str], "
                 "\"dates_mentioned\": [str], \"language\": str}"},
                {"role": "user", "content": f"Document : {filename}\n\n{text[:15000]}"},
            ],
            "temperature": 0.1,
            "max_tokens": extraction_max_tokens,
            "response_format": {"type": "json_object"},
        }

        logger.info(f"Extraction générique via {provider} ({model})...")
        async with httpx.AsyncClient(timeout=60.0) as client:
            for attempt in range(3):
                resp = await client.post(url, headers=headers, json=payload)
                if resp.status_code == 429 and attempt < 2:
                    wait = 2 ** (attempt + 1)  # 2s, 4s
                    logger.warning(f"Rate limit Groq, attente {wait}s...")
                    await asyncio.sleep(wait)
                    continue
                resp.raise_for_status()
                result = resp.json()
                break

        content = result["choices"][0]["message"]["content"]

        # Essayer JSON direct, puis fallback regex
        try:
            data = json.loads(content)
        except json.JSONDecodeError:
            data = _extract_json(content)

        if not data:
            logger.warning(f"Impossible d'extraire le JSON de la réponse Groq pour {filename}")
            return None

        doc_type = detect_doc_type(filename, text)
        meta = DocumentMetadata(
            source_file=filename,
            doc_type=doc_type,
            title=data.get("title", ""),
            summary=data.get("summary", ""),
            key_topics=data.get("key_topics", []),
            entities=data.get("entities", []),
            dates_mentioned=data.get("dates_mentioned", []),
            language=data.get("language", ""),
            word_count=len(text.split()),
        )
        meta.structured_json = meta.model_dump_json()
        logger.info(f"📄 {doc_type} extrait : {meta.title or filename}")
        return meta

    except Exception as e:
        logger.warning(f"⚠️ Extraction générique échouée pour {filename}: {e}")
        return None


async def extract_document(text: str, filename: str = "",
                           prefer_cloud: bool = True) -> Optional[DocumentMetadata]:
    """Point d'entrée principal : extraction universelle de document.

    Détecte automatiquement le type et adapte l'extraction.
    Pour les CV, utilise l'extraction CV spécialisée.
    Pour tous les autres documents, utilise l'extraction générique.
    """
    doc_type = detect_doc_type(filename, text)
    logger.info(f"📋 Extraction document : {filename} (type={doc_type})")

    # CV → extraction spécialisée avec CVStructure
    if doc_type == "CV":
        from src.cv_extractor import extract_cv, CVStructure, format_cv_for_context
        cv = await extract_cv(text, filename, prefer_cloud=prefer_cloud)
        if cv:
            meta = DocumentMetadata(
                source_file=filename,
                doc_type="CV",
                title=cv.nom or filename,
                summary=cv.resume_global or "",
                key_topics=[e.poste for e in cv.experiences[:3]] +
                           [c.domaine for c in cv.competences[:3]],
                entities=[e.entreprise for e in cv.experiences] +
                         [f.etablissement for f in cv.formations],
                dates_mentioned=[e.dates for e in cv.experiences if e.dates] +
                                [f.dates for f in cv.formations if f.dates],
                language="Français",
                word_count=len(text.split()),
            )
            # Stocker le CV complet dans structured_json pour usage avancé
            meta.structured_json = cv.model_dump_json()
            logger.info(f"✅ CV extrait : {cv.nom} "
                        f"({len(cv.experiences)} expériences)")
            return meta

    # Tous les autres documents → extraction générique
    if prefer_cloud:
        meta = await extract_generic_cloud(text, filename)
        if meta:
            return meta

    # Fallback extractif simple si LLM indisponible
    logger.info(f"Fallback extractif pour {filename}")
    lines = text.strip().split("\n")
    meaningful = [l.strip() for l in lines if len(l.strip()) > 30]
    summary = "\n".join(meaningful[:5]) if meaningful else text[:500]

    return DocumentMetadata(
        source_file=filename,
        doc_type=doc_type,
        title=filename,
        summary=summary[:1000],
        word_count=len(text.split()),
    )


def format_doc_for_context(meta: DocumentMetadata) -> str:
    """Formate les métadonnées structurées pour injection RAG."""
    if meta.doc_type == "CV" and meta.structured_json:
        # Pour les CV, essayer de charger le JSON complet pour un format riche
        try:
            from src.cv_extractor import CVStructure, format_cv_for_context
            cv = CVStructure.from_json(meta.structured_json, meta.source_file)
            if cv:
                return format_cv_for_context(cv)
        except Exception:
            pass
    return meta.format_for_context()


