# FICHIER: src/learning/optimizer.py  (424 lignes)
# ═══════════════════════════════════════════════════

"""
NURU V9 — StrategyOptimizer : ajuste automatiquement les paramètres du système.

Analyse les métriques de performance issues de PerformanceTracker
et produit des ajustements plafonnés pour :
- RAG score threshold
- Cloud-only / routing thresholds
- Suggestions de prompts depuis ErrorMemory

Stocke l'historique des ajustements dans SQLite (adjustment_log).
"""

import json
import logging
import os
import sqlite3
import time
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Optional

logger = logging.getLogger(__name__)

OPTIMIZER_DB = os.path.expanduser("~/.nuru/optimizer.db")


@dataclass
class Adjustment:
    """Un ajustement de paramètre proposé par StrategyOptimizer.

    Attributes:
        param: Nom du paramètre à ajuster
        current: Valeur actuelle
        proposed: Valeur proposée
        reason: Justification textuelle de l'ajustement
        applied: True si l'ajustement a été appliqué
        timestamp: Timestamp Unix de création
    """
    param: str
    current: Any
    proposed: Any
    reason: str = ""
    applied: bool = False
    timestamp: float = 0.0


class StrategyOptimizer:
    """Optimiseur stratégique qui ajuste les paramètres du système.

    Analyser les métriques de performance et produit des ajustements
    plafonnés pour les seuils RAG, de routage, et les suggestions de prompts.

    Règles d'ajustement :
    1. Si rag_empty_rate > 0.30 → baisser rag_score_threshold
    2. Si hallucination_rate > 0.10 → baisser cloud_only_threshold
    3. Si error_memory fourni → suggérer prompt addition
    4. Si task_success_rate < 0.50 → suggérer révision routage
    """

    # Bornes et limites par paramètre
    ADJUSTMENT_LIMITS: dict[str, dict[str, float]] = {
        "rag_score_threshold": {"min": 0.20, "max": 0.60, "delta_max": 0.05},
        "cloud_only_threshold": {"min": 0.30, "max": 0.90, "delta_max": 0.03},
        "routing_confidence": {"min": 0.30, "max": 0.95, "delta_max": 0.03},
    }

    # Métriques critiques analysées
    CRITICAL_METRICS: set[str] = {
        "rag_recall_at_5",
        "hallucination_rate",
        "task_success_rate",
    }

    def __init__(self, db_path: Optional[str] = None, error_memory=None):
        """Initialise l'optimiseur.

        Args:
            db_path: Chemin vers la base SQLite (défaut: ~/.nuru/optimizer.db)
            error_memory: Instance optionnelle de ErrorMemory pour suggestions
        """
        self.db_path = db_path or OPTIMIZER_DB
        self.error_memory = error_memory
        self._ensure_db()

    def _ensure_db(self):
        """Crée la base et la table adjustment_log si nécessaire."""
        Path(self.db_path).parent.mkdir(parents=True, exist_ok=True)
        conn = self._get_conn()
        try:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS adjustment_log (
                    id TEXT PRIMARY KEY,
                    timestamp REAL NOT NULL,
                    param TEXT NOT NULL,
                    old_value TEXT NOT NULL,
                    new_value TEXT NOT NULL,
                    reason TEXT DEFAULT '',
                    applied INTEGER DEFAULT 0
                )
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_adjustment_timestamp
                ON adjustment_log(timestamp)
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_adjustment_param
                ON adjustment_log(param)
            """)
            conn.commit()
        finally:
            conn.close()

    def _get_conn(self):
        """Retourne une connexion SQLite avec row_factory activée."""
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        return conn

    # ── Analyse ────────────────────────────────────────────────────

    def analyze(self, metrics: dict) -> list[Adjustment]:
        """Analyse les métriques et produit une liste d'ajustements.

        Règles appliquées :
        1. Si rag_empty_rate > 0.30 → baisser rag_score_threshold de delta_max
        2. Si hallucination_rate > 0.10 → baisser cloud_only_threshold de delta_max
        3. Si error_memory fourni → suggérer prompt addition
        4. Si task_success_rate < 0.50 → suggérer révision routage (routing_confidence)

        Args:
            metrics: Dictionnaire de métriques (clés : rag_empty_rate,
                     hallucination_rate, task_success_rate, ...)

        Returns:
            Liste d'objets Adjustment (non appliqués)
        """
        adjustments: list[Adjustment] = []
        now = time.time()

        # Règle 1 : Rag empty rate trop élevé → baisser seuil RAG
        rag_empty_rate = metrics.get("rag_empty_rate", 0.0)
        if rag_empty_rate > 0.30:
            delta = self.ADJUSTMENT_LIMITS["rag_score_threshold"]["delta_max"]
            current = metrics.get("rag_score_threshold", 0.50)
            proposed = max(
                self.ADJUSTMENT_LIMITS["rag_score_threshold"]["min"],
                current - delta,
            )
            adjustments.append(Adjustment(
                param="rag_score_threshold",
                current=current,
                proposed=proposed,
                reason=(
                    f"rag_empty_rate={rag_empty_rate:.2f} > 0.30 : "
                    f"baisse de {current:.2f} à {proposed:.2f}"
                ),
                timestamp=now,
            ))

        # Règle 2 : Hallucination rate trop élevé → baisser cloud_only_threshold
        hallucination_rate = metrics.get("hallucination_rate", 0.0)
        if hallucination_rate > 0.10:
            delta = self.ADJUSTMENT_LIMITS["cloud_only_threshold"]["delta_max"]
            current = metrics.get("cloud_only_threshold", 0.70)
            proposed = max(
                self.ADJUSTMENT_LIMITS["cloud_only_threshold"]["min"],
                current - delta,
            )
            adjustments.append(Adjustment(
                param="cloud_only_threshold",
                current=current,
                proposed=proposed,
                reason=(
                    f"hallucination_rate={hallucination_rate:.2f} > 0.10 : "
                    f"baisse de {current:.2f} à {proposed:.2f}"
                ),
                timestamp=now,
            ))

        # Règle 3 : ErrorMemory disponible → suggérer prompt addition
        if self.error_memory is not None:
            try:
                stats = self.error_memory.get_stats()
                top_types = stats.get("top_types", [])
                if top_types:
                    prompt_suggestion = (
                        f"Attention aux erreurs fréquentes : {', '.join(top_types[:3])}. "
                        "Envisager d'ajuster les prompts pour ces types d'erreur."
                    )
                    adjustments.append(Adjustment(
                        param="prompt_addition",
                        current="",
                        proposed=prompt_suggestion,
                        reason=f"Erreurs fréquentes détectées : {', '.join(top_types[:3])}",
                        timestamp=now,
                    ))
            except Exception as e:
                logger.debug("StrategyOptimizer: erreur consultation ErrorMemory (%s)", e)

        # Règle 4 : Task success rate trop bas → suggérer révision routage
        task_success_rate = metrics.get("task_success_rate", 1.0)
        if task_success_rate < 0.50:
            delta = self.ADJUSTMENT_LIMITS["routing_confidence"]["delta_max"]
            current = metrics.get("routing_confidence", 0.70)
            proposed = max(
                self.ADJUSTMENT_LIMITS["routing_confidence"]["min"],
                current - delta,
            )
            adjustments.append(Adjustment(
                param="routing_confidence",
                current=current,
                proposed=proposed,
                reason=(
                    f"task_success_rate={task_success_rate:.2f} < 0.50 : "
                    f"baisse routage de {current:.2f} à {proposed:.2f}"
                ),
                timestamp=now,
            ))

        return adjustments

    # ── Validation ─────────────────────────────────────────────────

    def validate(self, adjustment: Adjustment) -> bool:
        """Valide qu'un ajustement ne dépasse pas les bornes définies.

        Vérifie :
        - Le paramètre est connu dans ADJUSTMENT_LIMITS
        - La valeur proposée est dans [min, max]
        - Le delta (|proposed - current|) ≤ delta_max

        Pour les paramètres non définis dans ADJUSTMENT_LIMITS
        (comme 'prompt_addition'), la validation passe toujours.

        Args:
            adjustment: L'ajustement à valider

        Returns:
            True si l'ajustement est valide, False sinon
        """
        limits = self.ADJUSTMENT_LIMITS.get(adjustment.param)

        # Paramètre non limité (ex: prompt_addition) → toujours valide
        if limits is None:
            return True

        # Vérifier les bornes
        proposed = adjustment.proposed
        if isinstance(proposed, (int, float)):
            if proposed < limits["min"] or proposed > limits["max"]:
                logger.debug(
                    "Ajustement %s hors bornes [%s, %s] : %s",
                    adjustment.param, limits["min"], limits["max"], proposed,
                )
                return False

            # Vérifier le delta max
            current = adjustment.current
            if isinstance(current, (int, float)):
                delta = abs(proposed - current)
                if delta > limits["delta_max"]:
                    logger.debug(
                        "Delta ajustement %s trop grand : %s > %s",
                        adjustment.param, delta, limits["delta_max"],
                    )
                    return False

        return True

    # ── Application ────────────────────────────────────────────────

    def apply(self, adjustment: Adjustment) -> bool:
        """Applique un ajustement validé et l'enregistre dans l'historique.

        L'ajustement est d'abord validé. S'il est valide, il est marqué
        comme appliqué et enregistré dans la table adjustment_log.

        Args:
            adjustment: L'ajustement à appliquer

        Returns:
            True si l'ajustement a été appliqué avec succès, False sinon
        """
        if not self.validate(adjustment):
            return False

        adjustment.applied = True
        adjustment_id = str(uuid.uuid4())

        conn = self._get_conn()
        try:
            conn.execute(
                """INSERT INTO adjustment_log
                   (id, timestamp, param, old_value, new_value, reason, applied)
                   VALUES (?, ?, ?, ?, ?, ?, ?)""",
                (
                    adjustment_id,
                    adjustment.timestamp or time.time(),
                    adjustment.param,
                    str(adjustment.current),
                    str(adjustment.proposed),
                    adjustment.reason,
                    1 if adjustment.applied else 0,
                ),
            )
            conn.commit()
            logger.info(
                "Ajustement appliqué : %s : %s → %s (%s)",
                adjustment.param, adjustment.current, adjustment.proposed,
                adjustment.reason,
            )
            return True
        except Exception as e:
            logger.error("Erreur application ajustement : %s", e)
            return False
        finally:
            conn.close()

    # ── Historique ─────────────────────────────────────────────────

    def get_history(self, limit: int = 20) -> list[dict]:
        """Retourne l'historique des ajustements appliqués.

        Les entrées sont triées par timestamp décroissant.

        Args:
            limit: Nombre maximum d'entrées à retourner

        Returns:
            Liste de dicts avec les clés : id, timestamp, param,
            old_value, new_value, reason, applied
        """
        conn = self._get_conn()
        try:
            rows = conn.execute(
                """SELECT id, timestamp, param, old_value, new_value,
                          reason, applied
                   FROM adjustment_log
                   ORDER BY timestamp DESC
                   LIMIT ?""",
                (limit,),
            ).fetchall()
            return [
                {
                    "id": row["id"],
                    "timestamp": row["timestamp"],
                    "param": row["param"],
                    "old_value": row["old_value"],
                    "new_value": row["new_value"],
                    "reason": row["reason"],
                    "applied": bool(row["applied"]),
                }
                for row in rows
            ]
        finally:
            conn.close()

    # ── Résumé ─────────────────────────────────────────────────────

    def get_summary(self) -> dict:
        """Produit un résumé des ajustements.

        Returns:
            dict avec :
            - total_adjustments: nombre total d'ajustements appliqués
            - params_modified: nombre de paramètres distincts modifiés
            - by_param: dict {param: count}
            - trend: tendance récente (liste des 5 derniers ajustements)
            - recent_week_count: nombre d'ajustements dans la dernière semaine
        """
        conn = self._get_conn()
        try:
            # Total
            total = conn.execute(
                "SELECT COUNT(*) FROM adjustment_log WHERE applied = 1"
            ).fetchone()[0]

            # Par paramètre
            by_param_rows = conn.execute(
                """SELECT param, COUNT(*) as cnt
                   FROM adjustment_log WHERE applied = 1
                   GROUP BY param ORDER BY cnt DESC"""
            ).fetchall()
            by_param = {row["param"]: row["cnt"] for row in by_param_rows}

            # Paramètres distincts
            params_modified = len(by_param)

            # Tendances : 5 derniers
            trend_rows = conn.execute(
                """SELECT param, old_value, new_value, reason, timestamp
                   FROM adjustment_log WHERE applied = 1
                   ORDER BY timestamp DESC LIMIT 5"""
            ).fetchall()
            trend = [
                {
                    "param": row["param"],
                    "from": row["old_value"],
                    "to": row["new_value"],
                    "reason": row["reason"],
                    "timestamp": row["timestamp"],
                }
                for row in trend_rows
            ]

            # Dernière semaine
            week_ago = time.time() - 7 * 24 * 3600
            recent_week_count = conn.execute(
                "SELECT COUNT(*) FROM adjustment_log WHERE applied = 1 AND timestamp >= ?",
                (week_ago,),
            ).fetchone()[0]

        finally:
            conn.close()

        return {
            "total_adjustments": total,
            "params_modified": params_modified,
            "by_param": by_param,
            "trend": trend,
            "recent_week_count": recent_week_count,
        }


# ═══════════════════════════════════════════════════
# FICHIER: src/learning/reflexion_engine.py  (350 lignes)
# ═══════════════════════════════════════════════════

"""NURU V15 Phase 4 — ReflexionEngine 2 passes (P1 #34).

Génération réflexive en 2 passes :
1. **Pass 1 (Generate)** : génère une réponse initiale via le LLM
2. **Pass 2 (Reflect)** : critique et raffine — vérifie les faits,
   détecte les contradictions, améliore la couverture

S'inspire des mécanismes Reflexion (Shinn et al. 2023) adaptés
pour M1 8 Go : pas de LLM-call reflexif dans la boucle critique,
utilisation d'heuristiques + contexte mémoire pour la réflexion.
"""

import logging
import re
import time
from collections.abc import Awaitable, Callable
from dataclasses import dataclass, field
from typing import Any, Optional

from src.learning.self_eval import SelfEvaluator, EvalResult

logger = logging.getLogger(__name__)


@dataclass
class ReflectionResult:
    """Résultat d'une génération réflexive 2 passes.

    Attributes:
        initial_response: Réponse brute Pass 1
        final_response: Réponse raffinée Pass 2
        critique: Analyse réflexive (faiblesses détectées)
        improvements_applied: Liste des améliorations effectuées
        eval_initial: Score d'auto-évaluation Pass 1
        eval_final: Score d'auto-évaluation Pass 2
        duration_ms: Temps total (Pass 1 + Pass 2)
        hallucination_warnings: Alertes d'hallucination détectées
    """
    initial_response: str = ""
    final_response: str = ""
    critique: list[str] = field(default_factory=list)
    improvements_applied: list[str] = field(default_factory=list)
    eval_initial: Optional[EvalResult] = None
    eval_final: Optional[EvalResult] = None
    duration_ms: float = 0.0
    hallucination_warnings: list[str] = field(default_factory=list)


class ReflexionEngine:
    """Moteur de réflexion 2 passes.

    Usage:
        engine = ReflexionEngine()
        result = await engine.reflect(
            query="Qu'est-ce que la photosynthèse ?",
            context="Les plantes vertes...",
            generate_fn=llm.generate,
        )
        # result.final_response = réponse raffinée
        # result.critique = ["manque détails sur chloroplastes", ...]
    """

    def __init__(
        self,
        self_eval: Optional[SelfEvaluator] = None,
        min_reflection_gain: float = 0.05,
        use_critique: bool = True,
    ):
        self.evaluator = self_eval or SelfEvaluator()
        self.min_reflection_gain = min_reflection_gain
        self.use_critique = use_critique

    async def reflect(
        self,
        query: str,
        context: str,
        generate_fn: Callable[[str], Awaitable[str]],
        memory_context: Optional[str] = None,
    ) -> ReflectionResult:
        """Exécute une génération réflexive 2 passes.

        Args:
            query: Question utilisateur
            context: Contexte RAG ou mémoire
            generate_fn: Fonction async de génération LLM
                         signature: (prompt: str) -> str
            memory_context: Contexte mémoire optionnel pour la réflexion

        Returns:
            ReflectionResult avec réponse raffinée et métadonnées
        """
        t0 = time.time()
        result = ReflectionResult()

        # ── Pass 1 : Génération initiale ──────────────────────────────
        prompt_1 = self._build_initial_prompt(query, context, memory_context)
        result.initial_response = await generate_fn(prompt_1)
        result.eval_initial = self.evaluator.evaluate(
            query=query,
            response=result.initial_response,
            context=context,
        )

        # ── Pass 2 : Critique réflexive ───────────────────────────────
        # V16+: Early stopping — si la réponse initiale est excellente,
        # on économise la Pass 2 (appel LLM + tokens)
        if (result.eval_initial and getattr(result.eval_initial, 'overall', 0.0) >= 0.9
                and not self._detect_hallucinations(
                    response=result.initial_response,
                    context=context,
                )):
            logger.info(f"⏭️ Reflexion: early stopping (score initial >= 0.9)")
            result.final_response = result.initial_response
            result.eval_final = result.eval_initial
            result.duration_ms = (time.time() - t0) * 1000
            return result

        result.critique = self._critique(
            query=query,
            response=result.initial_response,
            context=context,
        )

        # Détection d'hallucinations
        result.hallucination_warnings = self._detect_hallucinations(
            response=result.initial_response,
            context=context,
        )

        # Appliquer les améliorations
        if result.critique or result.hallucination_warnings:
            prompt_2 = self._build_reflection_prompt(
                query=query,
                context=context,
                initial=result.initial_response,
                critique=result.critique,
                warnings=result.hallucination_warnings,
                memory_context=memory_context,
            )
            result.final_response = await generate_fn(prompt_2)
            result.eval_final = self.evaluator.evaluate(
                query=query,
                response=result.final_response,
                context=context,
            )

            # Vérifier le gain
            if result.eval_final and result.eval_initial:
                gain = result.eval_final.overall - result.eval_initial.overall
                result.improvements_applied = [
                    f"Amélioration {gain:+.2f} ({len(result.critique)} points critiqués)"
                ]
                if gain < self.min_reflection_gain:
                    logger.info(
                        "Reflexion: gain %.3f < min %.3f, on garde l'initiale",
                        gain, self.min_reflection_gain,
                    )
                    result.final_response = result.initial_response
                else:
                    logger.info(
                        "Reflexion: gain %.3f, réponse raffinée utilisée",
                        gain,
                    )
        else:
            # Rien à améliorer
            result.final_response = result.initial_response
            result.eval_final = result.eval_initial

        result.duration_ms = (time.time() - t0) * 1000
        return result

    def _build_initial_prompt(
        self,
        query: str,
        context: str,
        memory_context: Optional[str] = None,
    ) -> str:
        """Construit le prompt de génération initiale."""
        parts = [
            f"Question : {query}",
            f"Contexte : {context}",
        ]
        if memory_context:
            parts.append(f"Mémoire pertinente : {memory_context}")
        parts.append(
            "Réponds à la question en utilisant uniquement le contexte "
            "fourni. Sois précis et concis."
        )
        return "\n\n".join(parts)

    def _build_reflection_prompt(
        self,
        query: str,
        context: str,
        initial: str,
        critique: list[str],
        warnings: list[str],
        memory_context: Optional[str] = None,
    ) -> str:
        """Construit le prompt de réflexion (Pass 2)."""
        parts = [
            f"Question originale : {query}",
            f"Contexte : {context}",
        ]
        if memory_context:
            parts.append(f"Mémoire pertinente : {memory_context}")

        parts.append(f"Réponse initiale :\n{initial}")

        if critique:
            parts.append(
                "Points à améliorer :\n- " + "\n- ".join(critique)
            )

        if warnings:
            parts.append(
                "⚠️ Vérifications nécessaires :\n- "
                + "\n- ".join(warnings)
            )

        parts.append(
            "Produis une version améliorée de la réponse qui corrige "
            "les points ci-dessus. Garde la même structure mais améliore "
            "la précision, la complétude et la clarté."
        )
        return "\n\n".join(parts)

    @staticmethod
    def _jaccard_similarity(a: str, b: str) -> float:
        """Jaccard sur bigrammes de caracteres — 0 dependance."""
        bigrams_a = set(a[i:i+2] for i in range(max(0, len(a) - 1)))
        bigrams_b = set(b[i:i+2] for i in range(max(0, len(b) - 1)))
        inter = len(bigrams_a & bigrams_b)
        union = len(bigrams_a | bigrams_b)
        return inter / union if union > 0 else 0.0

    def _critique(
        self,
        query: str,
        response: str,
        context: str,
    ) -> list[str]:
        """Analyse réflexive heuristique de la réponse.

        Vérifie :
        - Présence de répétitions
        - Couverture des mots-clés de la question
        - Signalement d'absence de contexte (hallucination potentielle)
        - Taille excessive ou insuffisante
        """
        issues: list[str] = []

        # 1. Répétitions flagrantes (Jaccard, seuil abaissé à 5 chars — détecte les boucles courtes)
        sentences = [s.strip() for s in re.split(r'[.!?]+', response) if len(s.strip()) > 5]
        if len(sentences) > 3:
            jaccard_scores = []
            for i in range(len(sentences) - 1):
                sim = self._jaccard_similarity(sentences[i], sentences[i+1])
                jaccard_scores.append(sim)
            avg_jaccard = sum(jaccard_scores) / len(jaccard_scores) if jaccard_scores else 0.0
            if avg_jaccard > 0.5:
                issues.append(
                    f"La réponse présente de fortes répétitions (similarité Jaccard moyenne="
                    f"{avg_jaccard:.2f}) — boucle ou redondance"
                )

        # 2. Couverture des mots-clés
        query_words = set(
            w.lower() for w in re.findall(r'\w{4,}', query)
            if w.lower() not in {"comment", "pourquoi", "quelle", "quels",
                                   "quelles", "est-ce", "c'est", "dans", "avec"}
        )
        if query_words:
            covered = sum(1 for w in query_words if w in response.lower())
            coverage = covered / len(query_words)
            if coverage < 0.5:
                issues.append(
                    f"Faible couverture thématique : {covered}/{len(query_words)} "
                    f"mots-clés de la question apparaissent dans la réponse"
                )

        # 3. Détection de phrases évasives
        hedging = re.findall(
            r"(je ne suis pas sûr|je ne sais pas|peut-être|"
            r"il est possible que|je n'ai pas d'information|"
            r"selon les sources disponibles|d'après le contexte)",
            response,
            re.IGNORECASE,
        )
        if len(hedging) > 2:
            issues.append(
                f"Hésitations excessives ({len(hedging)} occurrences) : "
                f"la réponse manque d'assurance"
            )

        # 4. Taille disproportionnée
        resp_words = len(response.split())
        ctx_words = len(context.split())
        if ctx_words > 0 and resp_words > ctx_words * 3:
            issues.append(
                f"Réponse trop longue ({resp_words} mots) "
                f"par rapport au contexte ({ctx_words} mots) — "
                f"risque d'hallucination"
            )
        if resp_words < 5:
            issues.append("Réponse trop courte — manque de développement")

        return issues

    def _detect_hallucinations(
        self,
        response: str,
        context: str,
    ) -> list[str]:
        """Détection heuristique d'hallucinations.

        Vérifie les affirmations factuelles non supportées par le contexte.
        Basé sur des règles simples (pas de LLM-call).
        """
        warnings: list[str] = []

        # 1. Chiffres et statistiques non supportés
        numbers = re.findall(r'\d+[%€$]|\d+%|[\d,]+(?:euros|dollars|fois)', response)
        for num in numbers[:3]:
            if num not in context:
                warnings.append(
                    f"Affirmation chiffrée non vérifiée dans le contexte : «{num}»"
                )

        # 2. Noms propres hors contexte
        proper = re.findall(r'\b[A-Z][a-zéèêëàâäùûüôöîïç]{2,}\b', response)
        context_proper = set(
            re.findall(r'\b[A-Z][a-zéèêëàâäùûüôöîïç]{2,}\b', context)
        )
        for name in proper:
            if name not in context_proper and len(name) > 3:
                warnings.append(
                    f"Entité nommée hors contexte : «{name}»"
                )
                break  # Un seul avertissement suffit

        # 3. Phrases qui ressemblent à des "inventions"
        if "en conclusion" in response.lower() and "en conclusion" not in context.lower():
            if response.lower().count("en conclusion") > 1:
                warnings.append(
                    "Structure de conclusion générique non supportée par le contexte"
                )

        return warnings


